<?php

declare(strict_types=1);

namespace Runalyze\Model\Route;

/**
 * Generated by PHPUnit_SkeletonGenerator 1.2.0 on 2014-11-10 at 18:38:24.
 */
final class LoopTest extends \PHPUnit\Framework\TestCase
{
    public function testRouteLoop(): void
    {
        $Loop = new Loop(new Entity([
            Entity::GEOHASHES => ['u1xjhxf507s1', 'u1xjhxf6b7s9', 'u1xjhxfd8jyw', 'u1xjhxf6b7s9', 'u1xjhxffrhw4'],
        ]));

        $Loop->nextStep();
        $this->assertSame('u1xjhxf6b7s9', $Loop->geohash());
        $this->assertEqualsWithDelta(0.02279247104384903, $Loop->calculatedStepDistance(), 0.2);

        $Loop->setStepSize(2);
        $Loop->nextStep();
        $this->assertSame('u1xjhxf6b7s9', $Loop->geohash());
        $this->assertEqualsWithDelta(0.0, $Loop->calculatedStepDistance(), PHP_FLOAT_EPSILON);

        $Loop->nextStep();
        $this->assertTrue($Loop->isAtEnd());
    }
}
